___CSS_LOADER_EXPORT___.push([module.id, `/* Collection Detail Panel - Slide-over from right */

.panel-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.15);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    z-index: 60000;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.3s ease, visibility 0.3s ease;
    pointer-events: none;
}

.panel-overlay.visible {
    opacity: 1;
    visibility: visible;
    /* Keep pointer-events: none so clicks pass through to collections underneath */
    pointer-events: none;
}

.collection-detail-panel {
    position: fixed;
    top: 0;
    right: 0;
    width: 340px;
    max-width: 85vw;
    height: 100%;
    background: var(--bg-color);
    box-shadow: -4px 0 24px rgba(0, 0, 0, 0.2);
    z-index: 60000;
    display: flex;
    flex-direction: column;
    transform: translateX(100%);
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
    pointer-events: auto;
}

.collection-detail-panel.open {
    transform: translateX(0);
}

.collection-detail-panel.closing {
    transform: translateX(100%);
}

/* Panel Header */
.panel-header {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    padding: 8px 12px;
    border-bottom: 1px solid var(--divider-color);
    background: var(--section-bg-color);
}

.panel-close-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 5px 12px;
    border: 1px solid rgba(255, 255, 255, 0.18);
    background: rgba(255, 255, 255, 0.08);
    border-radius: 6px;
    color: var(--text-color);
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 12px;
    font-weight: 500;
    opacity: 0.8;
}

.panel-close-btn:hover {
    background: rgba(239, 68, 68, 0.15);
    border-color: rgba(239, 68, 68, 0.3);
    color: #ef4444;
    opacity: 1;
}

[data-theme="dark"] .panel-close-btn {
    border-color: rgba(255, 255, 255, 0.12);
    background: rgba(255, 255, 255, 0.05);
}

/* Collection Info Section */
.panel-collection-info {
    padding: 0 16px 16px;
    background: var(--section-bg-color);
    border-bottom: 1px solid var(--divider-color);
    position: relative;
}

.panel-color-bar {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 4px;
    border-radius: 0;
}

.panel-title-section {
    padding-top: 12px;
}

.panel-title-row {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.panel-title {
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--text-color);
    margin: 0;
    word-break: break-word;
    flex: 1;
    min-width: 0;
}

.panel-title-edit {
    flex: 1;
    min-width: 200px;
}

.panel-title-edit .auto-save-textbox {
    font-size: 1.25rem;
    font-weight: 600;
}

.panel-edit-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border: none;
    background: transparent;
    border-radius: 6px;
    color: var(--text-secondary-color);
    cursor: pointer;
    transition: all 0.2s ease;
    opacity: 0.6;
}

.panel-edit-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    color: var(--text-color);
    opacity: 1;
}

.panel-incognito-badge {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4px 8px;
    background: rgba(107, 114, 128, 0.2);
    border-radius: 12px;
    color: var(--text-secondary-color);
}

.panel-recent-badge {
    display: inline-flex;
    align-items: center;
    padding: 2px 8px;
    background: rgba(34, 197, 94, 0.15);
    border: 1px solid rgba(34, 197, 94, 0.3);
    border-radius: 12px;
    font-size: 11px;
    font-weight: 600;
    color: rgba(34, 197, 94, 1);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* Panel metadata */
.panel-meta {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 8px;
    font-size: 13px;
    color: var(--text-secondary-color);
}

.panel-meta-item {
    opacity: 0.8;
}

.panel-meta-separator {
    opacity: 0.4;
}

/* Favicon preview in panel */
.panel-favicons-preview {
    display: flex;
    align-items: center;
    gap: 4px;
    margin-top: 12px;
    padding: 8px 12px;
    background: rgba(255, 255, 255, 0.05);
    border-radius: 8px;
    flex-wrap: wrap;
}

.panel-favicon {
    width: 20px;
    height: 20px;
    border-radius: 4px;
    object-fit: contain;
    background: var(--bg-color);
    padding: 2px;
}

.panel-favicon-more {
    font-size: 12px;
    color: var(--text-secondary-color);
    padding: 2px 8px;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    font-weight: 500;
}

/* Panel actions */
.panel-actions {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-top: 16px;
}

.panel-action-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 6px 10px;
    border: none;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    flex-shrink: 0;
}

.panel-action-btn.primary {
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--gradient-purple) 100%);
    color: white;
    box-shadow: 0 2px 6px rgba(var(--primary-color-rgb, 52, 152, 219), 0.3);
}

.panel-action-btn.primary:hover {
    background: linear-gradient(135deg, var(--gradient-purple) 0%, var(--primary-color) 100%);
    transform: translateY(-1px);
    box-shadow: 0 3px 8px rgba(var(--primary-color-rgb, 52, 152, 219), 0.4);
}

.panel-action-btn.flex-grow {
    flex: 1 1 auto;
    flex-shrink: 1;
    max-width: 150px;
}

.panel-action-group {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: nowrap;
    width: 100%;
}

.panel-action-btn.secondary {
    background: rgba(255, 255, 255, 0.1);
    color: var(--text-color);
    padding: 6px 8px;
    border: 1px solid rgba(255, 255, 255, 0.15);
}

.panel-action-btn.secondary:hover {
    background: rgba(255, 255, 255, 0.15);
    border-color: rgba(255, 255, 255, 0.25);
}

.panel-action-btn.danger {
    background: rgba(239, 68, 68, 0.15);
    color: #ef4444;
    padding: 6px 8px;
    border: 1px solid rgba(239, 68, 68, 0.2);
}

.panel-action-btn.danger:hover {
    background: rgba(239, 68, 68, 0.25);
    border-color: rgba(239, 68, 68, 0.4);
}

.panel-action-btn.stop-tracking {
    background: rgba(251, 146, 60, 0.15);
    color: #fb923c;
    padding: 6px 8px;
    border: 1px solid rgba(251, 146, 60, 0.2);
}

.panel-action-btn.stop-tracking:hover {
    background: rgba(251, 146, 60, 0.25);
    border-color: rgba(251, 146, 60, 0.4);
}

/* Panel tab search */
.panel-search-bar {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0 12px;
    padding: 7px 12px;
    border-radius: 8px;
    border: 1px solid var(--divider-color);
    background: var(--section-bg-color);
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    flex-shrink: 0;
}

.panel-search-bar:focus-within {
    border-color: var(--primary-color);
    box-shadow: 0 0 0 2px rgba(var(--primary-color-rgb, 52, 152, 219), 0.15);
}

.panel-search-icon {
    flex-shrink: 0;
    color: var(--text-secondary-color);
    opacity: 0.5;
    transition: opacity 0.2s ease;
}

.panel-search-bar:focus-within .panel-search-icon {
    opacity: 0.85;
    color: var(--primary-color);
}

.panel-search-input {
    flex: 1;
    min-width: 0;
    border: none;
    background: transparent;
    color: var(--text-color);
    font-size: 13px;
    font-weight: 500;
    font-family: inherit;
    outline: none;
}

.panel-search-input::placeholder {
    color: var(--text-secondary-color);
    opacity: 0.5;
}

.panel-search-clear {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    border: none;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 50%;
    color: var(--text-secondary-color);
    cursor: pointer;
    flex-shrink: 0;
    transition: background 0.15s ease, color 0.15s ease;
}

.panel-search-clear:hover {
    background: rgba(239, 68, 68, 0.15);
    color: #ef4444;
}

[data-theme="dark"] .panel-search-bar {
    background: rgba(255, 255, 255, 0.03);
    border-color: rgba(255, 255, 255, 0.1);
}

[data-theme="dark"] .panel-search-bar:focus-within {
    border-color: var(--primary-color);
    box-shadow: 0 0 0 2px rgba(var(--primary-color-rgb, 52, 152, 219), 0.12);
}

/* Panel content (tabs area) */
.panel-content {
    flex: 1;
    overflow-y: auto;
    padding: 0;
}

.panel-content .expanded-content {
    padding: 12px;
}

.panel-content .tab-actions-toolbar {
    margin-bottom: 12px;
}

.panel-content .tabs-section {
    padding-bottom: 40px;
}

/* Custom scrollbar for panel */
.panel-content::-webkit-scrollbar {
    width: 6px;
}

.panel-content::-webkit-scrollbar-track {
    background: transparent;
}

.panel-content::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.2);
    border-radius: 3px;
}

.panel-content::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.3);
}

/* Dark mode adjustments */
[data-theme="dark"] .collection-detail-panel {
    box-shadow: -4px 0 32px rgba(0, 0, 0, 0.5);
}

[data-theme="dark"] .panel-overlay {
    background: rgba(0, 0, 0, 0.25);
}

[data-theme="dark"] .panel-action-btn.secondary {
    background: rgba(255, 255, 255, 0.05);
    border-color: rgba(255, 255, 255, 0.1);
}

[data-theme="dark"] .panel-action-btn.secondary:hover {
    background: rgba(255, 255, 255, 0.1);
}

/* Responsive adjustments */
@media (max-width: 480px) {
    .collection-detail-panel {
        width: 100%;
        max-width: 100%;
    }
}

/* Animation for content appearance */
.collection-detail-panel.open .panel-collection-info {
    animation: panelContentSlideIn 0.4s ease-out 0.1s both;
}

.collection-detail-panel.open .panel-content {
    animation: panelContentSlideIn 0.4s ease-out 0.15s both;
}

@keyframes panelContentSlideIn {
    from {
        opacity: 0;
        transform: translateX(20px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}
