/* iOS 26 Liquid Glass Footer Design */
footer {
	/* Liquid Glass Effect */
	background: var(--section-bg-color);
	backdrop-filter: blur(2px) saturate(180%);
	-webkit-backdrop-filter: blur(2px) saturate(180%);
	border: 1px solid rgb(146 146 146 / 37%);
	box-shadow:
		0 4px 32px rgb(255 255 255 / 68%), inset 0 4px 30px rgb(255 255 255 / 23%);
	/* Oval Shape - Elongated with perfect half circles on ends */
	border-radius: 50px;

	/* Floating Position */
	position: fixed;
	bottom: 10px;
	left: 50%;
	transform: translateX(-50%);

	/* Size and Layout */
	width: 55%;
	max-width: 800px;
	min-width: 420px;
	height: 45px;
	padding: 2px 30px;

	/* Grid Layout */
	display: grid;
	grid-template-columns: 1fr auto 1fr;
	align-items: center;

	z-index: 1000;

	/* Subtle Animation */
	transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

footer::after {
	content: '';
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	border-radius: 2rem;
	backdrop-filter: blur(1px);
	opacity: 0.6;
	z-index: -1;
	filter: blur(1px) drop-shadow(10px 4px 6px black) brightness(115%);
}

footer:hover {
	box-shadow:
		0 12px 48px rgba(0, 0, 0, 0.15),
		0 4px 24px rgba(0, 0, 0, 0.08),
		inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

/* Dark mode adjustments */
[data-theme="dark"] footer {
	border: 1px solid rgba(255, 255, 255, 0.1);
	box-shadow:
		0 8px 32px rgba(0, 0, 0, 0.3),
		0 2px 16px rgba(0, 0, 0, 0.2),
		inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

[data-theme="dark"] footer:hover {
	box-shadow:
		0 12px 48px rgba(0, 0, 0, 0.4),
		0 4px 24px rgba(0, 0, 0, 0.25),
		inset 0 1px 0 rgba(255, 255, 255, 0.15);
}

/* Left Section */
.footer_left {
	display: flex;
	align-items: center;
	gap: 15px;
	justify-content: flex-start;
}

/* Center Section */
.footer_center {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	text-align: center;
	font-weight: 600;
	color: var(--footer-text-color);
	line-height: 1;
	gap: 2px;
}

.version {
	font-size: 0.7em;
	color: #9752ff;
	font-weight: 800;
	opacity: 0.9;
}

/* Sync Status */
#last_sync {
	font-size: 0.75em;
	display: flex;
	color: var(--footer-text-color);
	align-items: center;
	gap: 6px;
	opacity: 0.9;
}

.footer-sync-dot {
	width: 7px;
	height: 7px;
	border-radius: 50%;
	flex-shrink: 0;
	transition: all 0.3s ease;
}

.footer-sync-dot.connected {
	background: #34c759;
	box-shadow: 0 0 6px rgba(52, 199, 89, 0.5);
}

.footer-sync-dot.syncing {
	background: #ffcc00;
	box-shadow: 0 0 6px rgba(255, 204, 0, 0.5);
	animation: pulse-footer-dot 1.4s ease-in-out infinite;
}

.footer-sync-dot.disconnected {
	background: #8e8e93;
	box-shadow: none;
}

@keyframes pulse-footer-dot {
	0%, 100% { opacity: 1; transform: scale(1); }
	50% { opacity: 0.5; transform: scale(0.85); }
}

footer svg {
	height: 1.2em;
	width: 1.2em;
	fill: var(--footer-text-color);
}

/* Right Section */
.footer_right {
	display: flex;
	flex-direction: column;
	align-items: flex-end;
	justify-content: center;
	font-size: 0.8em;
	font-weight: 400;
	gap: 6px;
}

.footer_right a {
	text-decoration: none;
	color: var(--footer-text-color);
	opacity: 0.9;
	transition: all 300ms ease;
}

.footer_right a:hover {
	color: var(--link-hover-color);
	opacity: 1;
}

.footer_icons {
	display: flex;
	gap: 20px;
	align-items: center;
	margin-right: 18px;
}

.social_icon {
	fill: var(--footer-text-color);
	transition: all 400ms cubic-bezier(0.4, 0, 0.2, 1);
	opacity: 0.8;
	width: 24px;
	height: 24px;
}

.social_icon:hover {
	opacity: 1;
	transform: scale(1.10);
	transition-duration: 50ms;
}

.facebook:hover {
	fill: #1777f2;
}

.facebook_f {
	fill: var(--footer-bg-color);
}

.facebook:hover path.facebook_f {
	fill: white;
}

.twitter:hover {
	fill: #1da1f3;
}

.sync_msg {
	font-weight: 500;
}



@keyframes rotation {
	from {
		transform: rotate(359deg);
	}

	to {
		transform: rotate(0deg);
	}
}

.rotate {
	animation: rotation 2s infinite linear;
}

/* Enhanced Tabox Gradient for Liquid Glass */
.tabox-gradient {
	background: linear-gradient(135deg,
			var(--gradient-blue),
			var(--gradient-purple),
			var(--gradient-orange),
			#ff6b9d);
	-webkit-background-clip: text;
	background-clip: text;
	-webkit-text-fill-color: transparent;
	background-size: 300% 300%;
	/* Animation removed to reduce idle CPU usage - static gradient still looks great */
	background-position: 50% 50%;
	font-size: 1em;
	line-height: 1;
	font-weight: 700;
	letter-spacing: 0.5px;
}

/* Only animate on hover for interactive feedback without idle CPU cost */
.tabox-gradient:hover {
	animation: liquidGradientShift 4s ease-in-out infinite;
}

@keyframes liquidGradientShift {

	0%,
	100% {
		background-position: 0% 50%;
	}

	33% {
		background-position: 100% 0%;
	}

	66% {
		background-position: 50% 100%;
	}
