  position: static;
  top: auto;
  right: auto;
  margin: 0;
  white-space: nowrap;
  flex-shrink: 0;
}

.folder-color-inline-picker {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border-radius: 14px;
  background: rgba(79, 172, 254, 0.08);
  border: 1px solid rgba(79, 172, 254, 0.12);
  flex-wrap: nowrap;
}

.folder-color-inline-option {
  width: 16px;
  height: 16px;
  border-radius: 999px;
