  background: rgba(0, 0, 0, 0.4);
  box-shadow:
    0 2px 6px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.15);
}

/* Liquid glass sliding animations for window toggle */
@keyframes slide-to-current {
  0% {
    transform: translate(36px, 0) scale(1, 1);
  }

  40% {
    transform: translate(18px, 0) scale(1.3, 0.85);
  }

  70% {
    transform: translate(2px, 0) scale(1.4, 0.7);
  }

  85% {
    transform: translate(0, 0) scale(1.1, 0.95);
  }

  100% {
    transform: translate(0, 0) scale(1, 1);
  }
}

@keyframes slide-to-all {
  0% {
    transform: translate(0, 0) scale(1, 1);
  }

  40% {
    transform: translate(20px, 0) scale(1.3, 0.85);
  }

  70% {
    transform: translate(36px, 0) scale(1.4, 0.7);
  }

  85% {
    transform: translate(38px, 0) scale(1.1, 0.95);
  }

  100% {
    transform: translate(38px, 0) scale(1, 1);
  }
}

