    --card-color: var(--fp-current-windows-accent, #84CC16);
}

.fp-current-window-card .fp-card-badge.fp-card-badge-label {
    background: color-mix(in srgb, var(--fp-current-windows-accent, #84CC16) 14%, transparent);
    color: var(--fp-current-windows-accent, #84CC16);
}

.fp-current-window-card.fp-card.fp-card-selected {
    border-color: color-mix(in srgb, var(--fp-current-windows-accent, #84CC16) 68%, transparent);
    box-shadow:
        0 0 0 2px color-mix(in srgb, var(--fp-current-windows-accent, #84CC16) 20%, transparent),
        var(--fp-shadow-md);
}

[data-theme="dark"] .fp-current-window-card .fp-card-badge.fp-card-badge-label {
    background: color-mix(in srgb, var(--fp-current-windows-accent, #84CC16) 18%, rgba(255, 255, 255, 0.04));
}

[data-theme="dark"] .fp-current-window-card.fp-card.fp-card-selected {
