        0 0 0 2px color-mix(in srgb, var(--fp-current-windows-accent, #84CC16) 24%, transparent),
        var(--fp-shadow-md);
}

.fp-current-window-card .fp-card-meta-chip.current-window-status {
    background: rgba(148, 163, 184, 0.14);
    color: var(--settings-row-text-color);
}

.fp-current-window-card .fp-card-meta-chip.current-window-status.active {
    background: rgba(34, 197, 94, 0.14);
    color: #15803d;
}

.fp-current-window-card .fp-card-matching-tab-title .fp-card-search-match {
    background: color-mix(in srgb, var(--fp-current-windows-accent, #84CC16) 24%, transparent);
