    background: color-mix(in srgb, var(--fp-current-windows-accent, #84CC16) 30%, transparent);
}

[data-theme="dark"] .fp-current-window-card .fp-card-matching-tab-url .fp-card-search-match {
    background: color-mix(in srgb, var(--fp-current-windows-accent, #84CC16) 24%, transparent);
}

[data-theme="dark"] .fp-current-window-card .fp-card-meta-chip.current-window-status.active {
    color: #86efac;
}

