n\toverflow-x: hidden;\n\tpadding: 5px 0 4.2rem 6px;\n\tz-index: 90;\n\tfont-size: 16px;\n\tbox-sizing: border-box;\n}\n\n/* Grid view specific styling */\n.settings_body.grid-view {\n\tpadding-bottom: 3.5rem;\n}\n\n.collection-grid {\n\tdisplay: grid;\n\tgrid-template-columns: repeat(auto-fill, minmax(var(--tile-size), 1fr));\n\tgap: 0;\n\toverflow-y: auto;\n\topacity: 0;\n\tanimation: gridFadeIn 0.3s ease-out 0.1s forwards;\n\tpadding: 8px 8px 8px 14px;\n}\n\n.collections-virtual-spacer {\n\twidth: 100%;\n\tpointer-events: none;\n}\n\n@media (prefers-reduced-motion: reduce) {\n\t.setting_row {\n\t\ttransition: none;\n\t}\n\n\t.setting_row:hover:not(.expanded) {\n\t\ttransform: none;\n\t}\n}\n\n@keyframes gridFadeIn {\n\t0% {\n\t\topacity: 0;\n\t\ttransform: translateY(10px);\n\t}\n\t100% {\n\t\topacity: 1;\n\t\ttransform: translateY(0);\n\t}\n}\n\n.collection-list {\n\topacity: 0;\n\tanimation: listFadeIn 0.3s ease-out 0.1s forwards;\n\tcontain: layout paint;\n}\n\n@keyframes listFadeIn {\n\t0% {\n\t\topacity: 0;\n\t\ttransform: translateY(-10px);\n\t}\n\t100% {\n\t\topacity: 1;\n\t\ttransform: translateY(0);\n\t}\n}\n\n.setting_row {\n\tpadding: 2px 4px;\n\tbackground-color: transparent;\n\tmargin: 1px 0 1px 10px;\n\tborder: 1px solid var(--setting-row-border-color);\n\tborder-radius: 6px;\n\ttransition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n\tdisplay: flex;\n\tjustify-content: flex-start;\n\talign-items: center;\n\twidth: calc(99% - 10px);\n\tmin-height: 34px;\n\tposition: relative;\n\toverflow: hidden;\n\tbox-sizing: border-box;\n\twill-change: transform, box-shadow;\n\tcontain: layout paint;\n}\n\n/* Setting row now opens panel instead of inline expansion */\n.setting_row {\n\tcursor: pointer;\n}\n\n.collection-row-main {\n\tdisplay: flex;\n\tjustify-content: flex-start;\n\talign-items: center;\n\twidth: 100%;\n\tmin-height: 34px;\n}\n\n/* Enhanced Modern Liquid Glass Hover Effect for List Items - but not for expanded items */\n.setting_row:hover:not(.expand