___CSS_LOADER_EXPORT___.push([module.id, `/* Delete-with-confirmation inline button */

.del-confirm-wrapper {
    position: relative;
    display: flex;
    align-items: center;
    gap: 0;
    height: 32px;
    border-radius: 10px;
    transition: background 0.25s ease, box-shadow 0.25s ease;
}

.del-confirm-wrapper.is-confirming {
    background: rgba(224, 108, 117, 0.10);
    box-shadow: 0 0 0 1px rgba(224, 108, 117, 0.18);
    border-radius: 10px;
}

/* Trigger icon button */
.del-confirm-trigger {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 10px;
    background: transparent;
    color: #e06c75;
    cursor: pointer;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    flex-shrink: 0;
    position: relative;
    z-index: 2;
}

.del-confirm-trigger svg {
    width: 18px !important;
    height: 18px !important;
    stroke-width: 1.8;
    transition: transform 0.2s ease;
}

.del-confirm-trigger:hover {
    background: rgba(224, 108, 117, 0.15);
    transform: scale(1.08);
}

.del-confirm-trigger:active {
    transform: scale(0.92);
}

.del-confirm-trigger.active {
    color: #d94f5a;
    background: rgba(224, 108, 117, 0.18);
}

.del-confirm-trigger.active svg {
    transform: rotate(-8deg);
}

/* Sliding confirmation */
.del-confirm-slide {
    display: flex;
    align-items: center;
    overflow: hidden;
    width: 0;
    opacity: 0;
    transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1),
                opacity 0.2s ease 0.05s;
    transform-origin: left center;
}

.del-confirm-slide.open {
    width: 68px;
    opacity: 1;
}

/* Confirm button */
.del-confirm-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 26px;
    padding: 0 12px;
    margin-left: 2px;
    border: none;
    border-radius: 7px;
    background: #d94f5a;
    color: #fff;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.02em;
    cursor: pointer;
    white-space: nowrap;
    transition: all 0.2s ease;
    box-shadow: 0 1px 4px rgba(217, 79, 90, 0.25);
}

.del-confirm-btn:hover:not(:disabled) {
    background: #c93a45;
    box-shadow: 0 2px 8px rgba(217, 79, 90, 0.35);
    transform: translateY(-1px);
}

.del-confirm-btn:active:not(:disabled) {
    transform: translateY(0);
    box-shadow: 0 1px 2px rgba(217, 79, 90, 0.2);
}

.del-confirm-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Fullpage overrides */
.fp-detail-panel .del-confirm-trigger {
    width: 36px;
    height: 36px;
}

.fp-detail-panel .del-confirm-trigger svg {
    width: 20px !important;
    height: 20px !important;
}

.fp-detail-panel .del-confirm-wrapper {
    height: 36px;
}

.fp-detail-panel .del-confirm-btn {
    height: 28px;
    font-size: 13px;
    padding: 0 14px;
}

.fp-detail-panel .del-confirm-slide.open {
    width: 74px;
}
