___CSS_LOADER_EXPORT___.push([module.id, `.current-window-close-modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(15, 23, 42, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 70000;
    padding: 16px;
}

.current-window-close-modal {
    width: min(520px, 100%);
    background: var(--bg-color);
    border: 1px solid var(--divider-color);
    border-radius: 16px;
    box-shadow: 0 24px 48px rgba(0, 0, 0, 0.2);
    overflow: hidden;
    outline: none;
}

.current-window-close-modal-content {
    display: flex;
    flex-direction: column;
}

.current-window-close-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 18px 20px;
    border-bottom: 1px solid var(--divider-color);
}

.current-window-close-modal-title {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-size: 18px;
    font-weight: 700;
    color: var(--text-color);
}

.current-window-close-modal-title svg {
    color: #dc2626;
}

.current-window-close-modal-close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    border: none;
    border-radius: 10px;
    background: transparent;
    color: var(--settings-row-text-color);
    cursor: pointer;
}

.current-window-close-modal-close:hover {
    background: var(--setting-row-hover-bg-color);
}

.current-window-close-modal-body {
    display: flex;
    flex-direction: column;
    gap: 16px;
    padding: 20px;
}

.current-window-close-copy {
    margin: 0;
    color: var(--text-color);
    line-height: 1.5;
}

.current-window-close-form-group {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.current-window-close-form-group label {
    font-size: 13px;
    font-weight: 700;
    color: var(--settings-row-text-color);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.current-window-close-form-group input,
.current-window-close-form-group select {
    width: 100%;
    height: 42px;
    padding: 0 14px;
    border: 1px solid var(--divider-color);
    border-radius: 10px;
    background: var(--section-bg-color);
    color: var(--text-color);
    font-size: 14px;
}

.current-window-close-folder-select-wrapper {
    position: relative;
}

.current-window-close-folder-dot {
    position: absolute;
    top: 50%;
    right: 14px;
    width: 10px;
    height: 10px;
    border-radius: 999px;
    transform: translateY(-50%);
    pointer-events: none;
}

.current-window-close-modal-footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 10px;
    padding: 18px 20px 20px;
    border-top: 1px solid var(--divider-color);
}

.current-window-close-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    height: 40px;
    padding: 0 16px;
    border: 1px solid transparent;
    border-radius: 10px;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
}

.current-window-close-btn-cancel {
    background: transparent;
    border-color: var(--divider-color);
    color: var(--text-color);
}

.current-window-close-btn-cancel:hover {
    background: var(--setting-row-hover-bg-color);
}

.current-window-close-btn-secondary {
    background: rgba(239, 68, 68, 0.08);
    border-color: rgba(239, 68, 68, 0.24);
    color: #dc2626;
}

.current-window-close-btn-secondary:hover {
    background: rgba(239, 68, 68, 0.14);
}

.current-window-close-btn-primary {
    background: var(--primary-color);
    color: #fff;
}

.current-window-close-btn-primary:hover {
    filter: brightness(1.05);
}

.current-window-close-btn:disabled {
    opacity: 0.6;
    cursor: default;
}
