}

.fp-content-grouped-mode .fp-grouped-section-items:not(.fp-content-list-mode) .fp-sortable-drop-after::after {
    right: calc(-100% - 12px);
}

/* List / search mode: row-like placeholder above/below target row.
   Uses top:0;bottom:0 to match the actual row height instead of a
   fixed pixel value, then translateY shifts it into the gap. */
.fp-content-list-mode .fp-sortable-drop-before::before,
.fp-content-search-mode .fp-sortable-drop-before::before {
    top: 0;
    bottom: 0;
    left: 4px;
    right: 4px;
    border-radius: 10px;
    transform: translateY(calc(-100% - 6px));
}

.fp-content-list-mode .fp-sortable-drop-after::after,
.fp-content-search-mode .fp-sortable-drop-after::after {
    top: 0;
    bottom: 0;
    left: 4px;
    right: 4px;
    border-radius: 10px;
    transform: translateY(calc(100% + 6px));
}

/* Grouped list mode: row-like placeholder inside section lists */
.fp-content-grouped-mode .fp-grouped-section-items.fp-content-list-mode .fp-sortable-drop-before::before {
    top: 0;
    bottom: 0;
    left: 4px;
    right: 4px;
    border-radius: 10px;
    transform: translateY(calc(-100% - 6px));
}

.fp-content-grouped-mode .fp-grouped-section-items.fp-content-list-mode .fp-sortable-drop-after::after {
    top: 0;
    bottom: 0;
    left: 4px;
    right: 4px;
    border-radius: 10px;
    transform: translateY(calc(100% + 6px));
}

.fp-content-grid.fp-content-animate-entrance > div:nth-child(1)  { animation-delay: 0s; }
.fp-content-grid.fp-content-animate-entrance > div:nth-child(2)  { animation-delay: 0.03s; }
.fp-content-grid.fp-content-animate-entrance > div:nth-child(3)  { animation-delay: 0.06s; }
.fp-content-grid.fp-content-animate-entrance > div:nth-child(4)  { animation-delay: 0.09s; }
.fp-content-grid.fp-content-animate-entrance > div:nth-child(5)  { animation-delay: 0.12s; }
.fp-content-grid.fp-content-animate-entrance > div:nth-child(6)  { animation-delay: 0.15s; }
.fp-content-grid.fp-content-animate-entrance > div:nth-child(7)  { animation-delay: 0.18s; }
.fp-content-grid.fp-content-animate-entrance > div:nth-child(8)  { animation-delay: 0.21s; }
.fp-content-grid.fp-content-animate-entrance > div:nth-child(9)  { animation-delay: 0.24s; }
.fp-content-grid.fp-content-animate-entrance > div:nth-child(n+10) { animation-delay: 0.27s; }

@keyframes fp-card-enter {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* ---- Search mode ---- */
.fp-content-grid.fp-content-search-mode {
    grid-template-columns: 1fr;
    gap: 14px;
}

.fp-content-grid.fp-content-search-mode > div,
.fp-content-grid.fp-content-search-mode > div > div,
.fp-content-search-mode .fp-card {
    min-width: 0;
    width: 100%;
}

.fp-content-search-mode .fp-card {
    flex-direction: column;
}

.fp-content-search-mode .fp-card-color-bar {
    height: 3px;
    width: 100%;
}

.fp-content-search-mode .fp-card-actions .fp-card-action-btn.primary {
    flex: 0 0 auto;
}

/* ---- List mode ---- */
.fp-content-grid.fp-content-list-mode {
    grid-template-columns: 1fr;
    gap: 6px;
}

.fp-content-grid.fp-content-grouped-mode {
    display: block;
    padding: 10px 18px 24px;
}

.fp-grouped-section {
    margin-bottom: 10px;
    transition:
        outline-color var(--fp-duration) var(--fp-ease),
        background-color var(--fp-duration) var(--fp-ease);
}

.fp-grouped-section-header-dropzone {
    border-radius: 10px;
}

.fp-grouped-section-header-dropzone.is-over {
    outline: 2px dashed rgba(22, 152, 226, 0.4);
    outline-offset: 4px;
}

.fp-grouped-section-header {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 2px 8px;
}

.fp-grouped-section-header-reveal {
    animation: fp-section-reveal 0.78s var(--fp-ease, ease) both;
}

.fp-grouped-section-header-reveal::after {
    content: '';
    position: absolute;
    inset: -4px -8px;
    border-radius: 16px;
    border: 1px solid color-mix(in srgb, var(--primary-color) 22%, transparent);
    box-shadow:
        0 0 0 0 color-mix(in srgb, var(--primary-color) 0%, transparent),
        0 14px 28px -24px color-mix(in srgb, var(--primary-color) 30%, transparent);
    pointer-events: none;
    animation: fp-section-reveal-ring 0.78s ease-out both;
}

.fp-grouped-section-header-reveal.reduced-motion {
    animation: none;
    background: color-mix(in srgb, var(--primary-color) 10%, transparent);
    border-radius: 14px;
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--primary-color) 24%, transparent);
}

.fp-grouped-section-header-reveal.reduced-motion::after {
    animation: none;
    opacity: 1;
    inset: -2px -6px;
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--primary-color) 22%, transparent);
}

@keyframes fp-section-reveal {
    0% {
        transform: translateY(8px);
        opacity: 0.78;
    }
    45% {
        transform: translateY(0);
        opacity: 1;
    }
    100% {
        transform: translateY(0);
        opacity: 1;
    }
}

@keyframes fp-section-reveal-ring {
    0% {
        opacity: 0;
        transform: scale(0.985);
        box-shadow: 0 0 0 0 color-mix(in srgb, var(--primary-color) 0%, transparent);
    }
    45% {
        opacity: 1;
        transform: scale(1);
        box-shadow:
            0 0 0 8px color-mix(in srgb, var(--primary-color) 10%, transparent),
            0 18px 34px -24px color-mix(in srgb, var(--primary-color) 26%, transparent);
    }
    100% {
        opacity: 0;
        transform: scale(1.01);
        box-shadow: 0 0 0 0 color-mix(in srgb, var(--primary-color) 0%, transparent);
    }
}

.fp-grouped-section-header.clickable {
    cursor: pointer;
}

.fp-grouped-section-header.clickable:hover .fp-grouped-section-title,
.fp-grouped-section-header.clickable:hover .fp-grouped-section-toggle {
    color: var(--text-color);
    opacity: 1;
}

.fp-grouped-section-title-wrap {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
    width: 100%;
}

.fp-grouped-section-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--settings-row-text-color);
    opacity: 0.6;
}

.fp-grouped-section-color-indicator {
    width: 12px;
    height: 12px;
    border-radius: 999px;
    background: var(--fp-section-color, var(--primary-color));
    box-shadow:
        0 0 0 3px color-mix(in srgb, var(--fp-section-color, var(--primary-color)) 18%, transparent),
        0 4px 12px color-mix(in srgb, var(--fp-section-color, var(--primary-color)) 45%, transparent);
    flex-shrink: 0;
}

.fp-grouped-section-title {
    font-size: 13px;
    font-weight: 700;
    color: var(--text-color);
    letter-spacing: 0.06em;
    text-transform: uppercase;
    opacity: 0.94;
}

.fp-grouped-section-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 18px;
    height: 18px;
    padding: 0 6px;
    border-radius: 999px;
    background: rgba(22, 152, 226, 0.07);
    color: var(--settings-row-text-color);
    font-size: 12px;
    font-weight: 700;
    opacity: 0.8;
}

.fp-grouped-section-divider {
    flex: 1 1 auto;
    min-width: 28px;
    height: 1px;
    margin-left: 6px;
    border-radius: 999px;
    background: color-mix(in srgb, var(--text-color) 18%, transparent);
    opacity: 0.55;
}

[data-theme="dark"] .fp-grouped-section-divider {
    background: color-mix(in srgb, white 30%, transparent);
    opacity: 0.38;
}

.fp-grouped-section-body {
    padding: 0 0 6px;
    border-radius: 12px;
}

.fp-grouped-section-items {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--fp-card-min-width, 320px)), var(--fp-card-min-width, 320px)));
    gap: 12px;
    position: relative;
    justify-content: start;
}

.fp-grouped-section-items > div {
    min-height: 0;
}

.fp-grouped-section-items:not(.fp-content-list-mode) {
    grid-auto-rows: var(--fp-grid-card-height, 200px);
}

.fp-grouped-section-items:not(.fp-content-list-mode) > div,
.fp-grouped-section-items:not(.fp-content-list-mode) > div > div {
    height: 100%;
}

.fp-grouped-section-items:not(.fp-content-list-mode) .fp-card {
    height: 100%;
    min-height: 0;
}

.fp-grouped-section-items:not(.fp-content-list-mode) .fp-card-favicons {
    flex-wrap: wrap;
    min-height: 60px;
    max-height: 86px;
    align-content: center;
    align-items: center;
    overflow: hidden;
}

.fp-grouped-section-items:not(.fp-content-list-mode) .fp-card-favicon-strip {
    flex-wrap: wrap;
    align-content: center;
    overflow: hidden;
}

/* Keep root-level grouped cards stable: the favicon hover blur can flicker here */
.fp-grouped-section-root .fp-grouped-section-items:not(.fp-content-list-mode) .fp-card-favicon {
    transition: none;
}

.fp-grouped-section-root .fp-grouped-section-items:not(.fp-content-list-mode) .fp-card:hover .fp-card-favicon {
    filter: none;
    opacity: 1;
}

.fp-grouped-section-items:not(.fp-content-list-mode) .fp-card-footer {
    margin-top: 0;
    padding-top: 8px;
    flex: 1;
    display: grid;
    grid-template-rows: 1fr auto;
    align-items: stretch;
    gap: 8px;
}

.fp-grouped-section-items.fp-content-list-mode {
    grid-template-columns: 1fr;
    gap: 6px;
}

.fp-collection-insert-gap,
.fp-grouped-insert-gap {
    min-height: var(--fp-grid-card-height, 200px);
    border: 2px dashed rgba(22, 152, 226, 0.55);
    border-radius: var(--fp-card-radius, 16px);
    background:
        linear-gradient(
            135deg,
            rgba(22, 152, 226, 0.12) 0%,
            rgba(22, 152, 226, 0.05) 100%
        );
    box-shadow:
        0 0 0 1px rgba(22, 152, 226, 0.12),
        inset 0 0 0 1px rgba(255, 255, 255, 0.24);
    pointer-events: none;
}

.fp-collection-insert-gap.fp-content-list-mode,
.fp-grouped-insert-gap.fp-content-list-mode {
    min-height: 56px;
    border-radius: 12px;
}

.fp-grouped-empty-dropzone {
    padding: 12px 14px;
    border-radius: 12px;
    border: 1px dashed rgba(22, 152, 226, 0.22);
    background: transparent;
    color: var(--settings-row-text-color);
    font-size: 12px;
    text-align: center;
    opacity: 0.72;
}

.fp-grouped-empty-dropzone-wrapper {
    min-height: var(--fp-grid-card-height, 200px);
    border-radius: 12px;
    display: flex;
    align-items: stretch;
}

.fp-grouped-empty-dropzone-wrapper.is-over .fp-grouped-empty-dropzone {
    border: 2px dashed rgba(22, 152, 226, 0.55);
    background:
        linear-gradient(
            135deg,
            rgba(22, 152, 226, 0.12) 0%,
            rgba(22, 152, 226, 0.05) 100%
        );
    box-shadow:
        0 0 0 1px rgba(22, 152, 226, 0.12),
        inset 0 0 0 1px rgba(255, 255, 255, 0.24);
    opacity: 1;
}

.fp-grouped-empty-dropzone-wrapper.fp-content-list-mode {
    min-height: 72px;
}

.fp-grouped-empty-dropzone-wrapper .fp-grouped-empty-dropzone {
    width: 100%;
    min-height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
}

.fp-grouped-append-dropzone {
    height: 42px;
    margin-top: 8px;
    border-radius: 14px;
    border: 1px dashed transparent;
    transition: border-color var(--fp-duration) var(--fp-ease), background var(--fp-duration) var(--fp-ease);
}

.fp-grouped-append-dropzone.is-over {
    border-color: rgba(22, 152, 226, 0.36);
    background: rgba(22, 152, 226, 0.08);
}

.fp-grouped-section-items:not(.fp-content-list-mode) + .fp-grouped-append-dropzone {
    height: 28px;
    margin-top: 10px;
    border-radius: 12px;
}

[data-theme="dark"] .fp-grouped-empty-dropzone {
    border-color: rgba(96, 165, 250, 0.26);
}

.fp-content-list-mode .fp-card {
    min-height: auto;
    flex-direction: row;
    align-items: center;
}

.fp-content-list-mode .fp-card-color-bar {
    width: 3px;
    height: 100%;
    min-height: 52px;
}

.fp-content-list-mode .fp-card-body {
    flex-direction: row;
    align-items: center;
    gap: 16px;
    padding: 8px 16px;
}

.fp-content-list-mode .fp-card-title-row {
    flex: 1;
    min-width: 0;
}

.fp-content-list-mode .fp-card-title {
    -webkit-line-clamp: 1;
    font-size: 13.5px;
}

.fp-content-list-mode .fp-card.fp-card-has-top-badge .fp-card-top-badge-wrap {
    position: static;
    flex-shrink: 0;
    margin-left: 14px;
}

.fp-content-list-mode .fp-card.fp-card-has-top-badge .fp-card-body {
    padding-left: 0;
    padding-top: 8px;
}

/* Footer flattens into the row in list mode */
.fp-content-list-mode .fp-card-footer {
    display: contents;
}

.fp-content-list-mode .fp-card-favicons {
    flex-wrap: nowrap;
    min-width: 0;
    max-width: 180px;
    flex: 0 1 180px;
    overflow: hidden;
    padding-right: 12px;
    gap: 6px;
}

.fp-content-list-mode .fp-card-favicon-strip {
    flex-wrap: nowrap;
    overflow: hidden;
    -webkit-mask-image: linear-gradient(to right, #000 0, #000 calc(100% - 18px), transparent 100%);
    mask-image: linear-gradient(to right, #000 0, #000 calc(100% - 18px), transparent 100%);
}

/* Stats inline in list mode */
.fp-content-list-mode .fp-card-stats {
    flex-direction: row;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
    margin-left: auto;
}

.fp-content-list-mode .fp-card-meta {
    flex-shrink: 0;
    justify-content: flex-start;
}

.fp-content-list-mode .fp-card-time {
    flex-shrink: 0;
    text-align: left;
}

.fp-content-list-mode .fp-card-actions {
    position: static;
    background: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    transform: none;
    opacity: 0;
    padding: 0 12px;
    flex-shrink: 0;
}

.fp-content-list-mode .fp-card:hover .fp-card-actions {
    opacity: 1;
}

/* In list mode, Open button doesn't need to stretch */
.fp-content-list-mode .fp-card-actions .fp-card-action-btn.primary {
    flex: 0 0 auto;
}

.fp-content-list-mode .fp-card-action-menu {
    position: static;
    opacity: 0;
    order: 4;
    margin-right: 8px;
}

.fp-content-list-mode .fp-card:hover .fp-card-action-menu {
    opacity: 1;
}

.fp-content-list-mode .fp-card-body {
    order: 2;
}

.fp-content-list-mode .fp-card-actions {
    order: 3;
}

.fp-content-list-mode .fp-card.fp-card-has-matches {
    flex-direction: column;
    align-items: stretch;
}

.fp-content-list-mode .fp-card.fp-card-has-matches .fp-card-body {
    width: 100%;
}

.fp-content-list-mode .fp-card.fp-card-has-matches .fp-card-actions {
    position: absolute;
    background: linear-gradient(
        to top,
        var(--fp-surface-elevated, var(--settings-bg-color)) 65%,
        transparent
    );
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    padding: 10px 12px;
    order: initial;
}

.fp-content-list-mode .fp-card.fp-card-has-matches .fp-card-action-menu {
    position: absolute;
    order: initial;
    margin-right: 0;
}

/* ========================================
   Sessions View
   ======================================== */
.fp-content-sessions {
    display: flex;
    flex-direction: column;
    padding: 0 24px 24px;
    overflow-y: auto;
    flex: 1;
    min-height: 0;
}

.fp-content-sessions > .fp-content-empty-state-wrap {
    flex: 1;
}

.fp-toolbar-group-selection {
    display: flex;
    align-items: center;
    gap: 14px;
    flex-wrap: wrap;
}

.fp-toolbar-session-selection-pill {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    min-height: 38px;
    padding: 0 14px;
    border-radius: var(--fp-radius-xl, 20px);
    border: 1px solid color-mix(in srgb, #f59e0b 20%, var(--fp-border, var(--divider-color)));
    background: color-mix(in srgb, #f59e0b 9%, transparent);
    color: var(--text-color);
    white-space: nowrap;
}

.fp-toolbar-collection-selection-pill {
    border-color: color-mix(in srgb, var(--primary-color) 22%, var(--fp-border, var(--divider-color)));
    background: color-mix(in srgb, var(--primary-color) 10%, transparent);
}

.fp-toolbar-session-selection-count {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: -0.01em;
}

.fp-toolbar-session-selection-label {
    color: var(--settings-row-text-color);
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.fp-toolbar-session-clear-btn {
    color: #b91c1c;
}

.fp-toolbar-session-clear-btn:hover {
    background: rgba(239, 68, 68, 0.1);
    border-color: rgba(239, 68, 68, 0.22);
    color: #b91c1c;
}

.fp-toolbar-danger-btn {
    color: #b91c1c;
    border-color: rgba(239, 68, 68, 0.22);
}

.fp-toolbar-danger-btn:hover {
    background: rgba(239, 68, 68, 0.1);
    border-color: rgba(239, 68, 68, 0.3);
    color: #b91c1c;
}

.fp-toolbar-bulk-color-picker {
    min-height: 38px;
}

.fp-toolbar-group-collection-selection {
    width: 100%;
}

[data-theme="dark"] .fp-toolbar-session-selection-pill {
    background: color-mix(in srgb, #f59e0b 12%, rgba(255, 255, 255, 0.03));
    border-color: color-mix(in srgb, #f59e0b 24%, rgba(255, 255, 255, 0.1));
}

[data-theme="dark"] .fp-toolbar-collection-selection-pill {
    background: color-mix(in srgb, var(--primary-color) 14%, rgba(255, 255, 255, 0.03));
    border-color: color-mix(in srgb, var(--primary-color) 24%, rgba(255, 255, 255, 0.1));
}

[data-theme="dark"] .fp-toolbar-session-clear-btn {
    color: #fca5a5;
}

[data-theme="dark"] .fp-toolbar-session-clear-btn:hover {
    background: rgba(239, 68, 68, 0.14);
    border-color: rgba(248, 113, 113, 0.25);
    color: #fecaca;
}

[data-theme="dark"] .fp-toolbar-danger-btn {
    color: #fca5a5;
    border-color: rgba(248, 113, 113, 0.22);
}

[data-theme="dark"] .fp-toolbar-danger-btn:hover {
    background: rgba(239, 68, 68, 0.14);
    border-color: rgba(248, 113, 113, 0.3);
    color: #fecaca;
}

/* ---- Session Group Header ---- */
.fp-session-group-header {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 18px 4px 10px;
}

.fp-session-group-header:first-child {
    padding-top: 8px;
}

.fp-session-group-label {
    font-family: var(--fp-font-body);
    font-size: 13px;
    font-weight: 700;
    color: var(--text-color);
    text-transform: uppercase;
    letter-spacing: 0.06em;
    opacity: 0.7;
}

.fp-session-group-meta {
    font-family: var(--fp-font-body);
    font-size: 12px;
    font-weight: 500;
    color: var(--settings-row-text-color);
    opacity: 0.5;
}

/* ---- Session Group Cards Grid ---- */
.fp-session-group-cards {
    display: grid;
    --fp-grid-gap: 12px;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--fp-card-min-width, 320px)), var(--fp-card-min-width, 320px)));
    gap: var(--fp-grid-gap);
    padding-bottom: 6px;
}

.fp-session-group-cards:not(.fp-content-list-mode):not(.fp-content-search-mode) {
    --fp-grid-card-height: 200px;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--fp-card-min-width, 320px)), var(--fp-card-min-width, 320px)));
    justify-content: start;
}

.fp-session-group-cards:not(.fp-content-list-mode):not(.fp-content-search-mode) > .fp-session-card,
.fp-session-group-cards:not(.fp-content-list-mode):not(.fp-content-search-mode) > .fp-card {
    height: 100%;
    min-height: var(--fp-grid-card-height);
}

.fp-session-group-cards:not(.fp-content-list-mode):not(.fp-content-search-mode) .fp-card-favicons {
    flex-wrap: wrap;
    min-height: 60px;
    max-height: 86px;
    align-content: center;
    align-items: center;
    overflow: hidden;
}

.fp-session-group-cards:not(.fp-content-list-mode):not(.fp-content-search-mode) .fp-card-favicon-strip {
    flex-wrap: wrap;
    align-content: center;
    overflow: hidden;
}

.fp-session-group-cards:not(.fp-content-list-mode):not(.fp-content-search-mode) .fp-card-footer {
    margin-top: 0;
    padding-top: 8px;
    flex: 1;
    display: grid;
    grid-template-rows: 1fr auto;
    align-items: stretch;
    gap: 8px;
}

.fp-session-group-cards.fp-content-list-mode {
    grid-template-columns: 1fr;
    gap: 6px;
}

.fp-session-group-cards.fp-content-search-mode {
    grid-template-columns: 1fr;
    gap: 14px;
}

@media (max-width: 900px) {
    .fp-toolbar-group-selection {
        width: 100%;
    }

    .fp-toolbar-group-selection .fp-toolbar-btn-label {
        flex: 1 1 calc(50% - 7px);
        justify-content: center;
    }

    .fp-toolbar-session-selection-pill {
        width: 100%;
        justify-content: space-between;
    }
}

/* ========================================
   Card Right-Click Context Menu
   ======================================== */
.fp-card-ctx-menu {
    position: fixed;
    z-index: 9999;
    min-width: 210px;
    padding: 5px;
    border-radius: var(--fp-radius-sm, 10px);
    border: 1px solid var(--fp-border-strong, var(--divider-color));
    background: var(--fp-surface-elevated, var(--settings-bg-color));
    backdrop-filter: blur(16px) saturate(1.4);
    -webkit-backdrop-filter: blur(16px) saturate(1.4);
    box-shadow:
        0 8px 30px rgba(0, 0, 0, 0.14),
        0 2px 8px rgba(0, 0, 0, 0.06);
    animation: fp-card-ctx-in 0.12s ease-out both;
}

[data-theme="dark"] .fp-card-ctx-menu {
    box-shadow:
        0 8px 30px rgba(0, 0, 0, 0.4),
        0 2px 8px rgba(0, 0, 0, 0.22);
}

@keyframes fp-card-ctx-in {
    from { opacity: 0; transform: scale(0.96) translateY(-4px); }
    to { opacity: 1; transform: scale(1) translateY(0); }
}

.fp-card-ctx-item {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    padding: 8px 12px;
    border-radius: var(--fp-radius-xs, 6px);
    border: none;
    background: transparent;
    color: var(--text-color);
    font-family: var(--fp-font-body);
    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
    text-align: left;
    white-space: nowrap;
    transition: background var(--fp-duration, 0.15s) ease;
}

.fp-card-ctx-item:hover {
    background: var(--fp-border, var(--setting-row-hover-bg-color));
}

.fp-card-ctx-item svg {
    flex-shrink: 0;
    opacity: 0.6;
}

.fp-card-ctx-item:hover svg {
    opacity: 0.85;
}

/* Danger item */
.fp-card-ctx-danger {
    color: #DC2626;
}

.fp-card-ctx-danger:hover {
    background: rgba(220, 38, 38, 0.08);
}

[data-theme="dark"] .fp-card-ctx-danger {
    color: #f87171;
}

[data-theme="dark"] .fp-card-ctx-danger:hover {
    background: rgba(220, 38, 38, 0.15);
}

.fp-card-ctx-danger svg {
    opacity: 0.8;
}

/* Divider */
.fp-card-ctx-divider {
    height: 1px;
    margin: 4px 8px;
    background: var(--fp-border, var(--divider-color));
}

/* ---- Responsive ---- */
@media (min-width: 1600px) {
    .fp-content-grid {
        --fp-grid-gap: 14px;
        padding: 22px;
        gap: var(--fp-grid-gap);
    }
}

@media (max-width: 900px) {
    .fp-content-grid {
        --fp-grid-gap: 8px;
        grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
        padding: 12px;
        gap: var(--fp-grid-gap);
    }
    .fp-content-title-row {
        padding: 12px 16px 8px;
    }
    .fp-content-heading {
        gap: 6px;
        padding: 12px 14px 12px 16px;
        border-radius: 16px;
    }
    .fp-content-heading-main {
        gap: 8px;
    }
    .fp-content-title {
        white-space: normal;
    }
    .fp-toolbar-wrapper {
        padding: 4px 16px 10px;
    }
    .fp-toolbar-pill span {
        display: none;
    }
    .fp-toolbar-divider {
        margin: 0 2px;
    }
    .fp-toolbar-segment-btn {
        padding: 0 10px;
        font-size: 12px;
    }
    .fp-content-heading-subtitle {
        font-size: 12px;
    }
}

@media (prefers-reduced-motion: reduce) {
    .fp-content-grid > div,
    .fp-toolbar-add-menu {
        animation: none !important;
    }
    .fp-sortable-drop-before::before,
    .fp-sortable-drop-after::after {
        animation: none !important;
    }
}
