n    justify-content: center;\n    width: 28px;\n    height: 28px;\n    flex-shrink: 0;\n    border: none;\n    border-radius: 8px;\n    background: var(--primary-hover-bg);\n    color: var(--primary-color);\n    cursor: pointer;\n    transition: background 0.15s ease;\n}\n\n.cmd-palette-back-btn:hover {\n    background: rgba(22, 152, 226, 0.25);\n}\n\n.cmd-palette-scope-badge {\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    flex-shrink: 0;\n    padding: 3px 10px 3px 7px;\n    border-radius: 6px;\n    font-size: 0.8em;\n    font-weight: 600;\n    color: var(--text-color);\n    background: var(--primary-hover-bg);\n    max-width: 160px;\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n}\n\n.cmd-palette-scope-dot {\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n    flex-shrink: 0;\n}\n\n.cmd-palette-input {\n    flex: 1;\n    min-width: 0;\n    border: none;\n    outline: none;\n    background: transparent;\n    font-size: 0.95em;\n    color: var(--text-color);\n    font-family: inherit;\n}\n\n.cmd-palette-input::placeholder {\n    color: var(--text-color);\n    opacity: 0.4;\n}\n\n.cmd-palette-esc-hint {\n    flex-shrink: 0;\n    font-family: \"SF Mono\", Monaco, \"Cascadia Code\", \"Roboto Mono\", Consolas, \"Courier New\", monospace;\n    font-size: 0.7em;\n    padding: 2px 6px;\n    border-radius: 4px;\n    color: var(--text-color);\n    opacity: 0.4;\n    background: rgba(0, 0, 0, 0.05);\n    border: 1px solid rgba(0, 0, 0, 0.08);\n    line-height: 1;\n}\n\n[data-theme=\"dark\"] .cmd-palette-esc-hint {\n    background: rgba(255, 255, 255, 0.06);\n    border-color: rgba(255, 255, 255, 0.08);\n}\n\n/* ─── Results ─── */\n.cmd-palette-results {\n    flex: 1;\n    overflow-y: auto;\n    padding: 6px;\n    scroll-behavior: smooth;\n}\n\n.cmd-palette-results::-webkit-scrollbar {\n    width: 4px;\n}\n\n.cmd-palette-results::-webkit-scrollbar-thumb {\n    background: rgba(0, 0, 0, 0.15);\n    border-radius: 4px;\n}\n\n[data-theme=\"dark\"] .cmd-palette-results::-webkit-scrollbar-thumb {\n    background: rgba(255, 255, 255, 0.12);\n}\n\n/* ─── Section Labels ─── */\n.cmd-palette-section-label {\n    padding: 8px 10px 4px;\n    font-size: 0.7em;\n    font-weight: 600;\n    text-transform: uppercase;\n    letter-spacing: 0.06em;\n    color: var(--text-color);\n    opacity: 0.4;\n    user-select: none;\n}\n\n.cmd-palette-separator {\n    height: 1px;\n    margin: 4px 10px;\n    background: rgba(0, 0, 0, 0.06);\n}\n\n[data-theme=\"dark\"] .cmd-palette-separator {\n    background: rgba(255, 255, 255, 0.06);\n}\n\n/* ─── Result Row ─── */\n.cmd-palette-row {\n    display: flex;\n    align-items: center;\n    gap: 10px;\n    padding: 8px 10px;\n    border-radius: 8px;\n    cursor: pointer;\n    transition: background 0.1s ease;\n    position: relative;\n}\n\n.cmd-palette-row:hover {\n    background: var(--setting-row-hover-bg-color);\n}\n\n.cmd-palette-row.selected {\n    background: var(--primary-hover-bg);\n}\n\n.cmd-palette-row.selected::before {\n    content: '';\n    position: absolute;\n    left: 0;\n    top: 6px;\n    bottom: 6px;\n    width: 3px;\n    border-radius: 0 3px 3px 0;\n    background: var(--primary-color);\n}\n\n.cmd-palette-row.danger .cmd-palette-row-icon,\n.cmd-palette-row.danger .cmd-palette-row-label {\n    color: #DC2626;\n}\n\n[data-theme=\"dark\"] .cmd-palette-row.danger .cmd-palette-row-icon,\n[data-theme=\"dark\"] .cmd-palette-row.danger .cmd-palette-row-label {\n    color: #F87171;\n}\n\n/* ─── Row Elements ─── */\n.cmd-palette-color-dot {\n    width: 10px;\n    height: 10px;\n    border-radius: 50%;\n    flex-shrink: 0;\n    box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.08);\n}\n\n/* ─── Toggle Pill (settings rows) ─── */\n.cmd-palette-toggle-pill {\n    flex-shrink: 0;\n    font-size: 0.65em;\n    font-weight: 700;\n    letter-spacing: 0.04em;\n    padding: 2px 7px;\n    border-radius: 9px;\n    line-height: 1.3;\n    text-transform: uppercase;\n    background: rgba(0, 0, 0, 0.08);\n    color: var(--text-color);\n    opacity: 0.55;\n    transition: all 0.15s ease;\n}\n\n.cmd-palette-toggle-pill.on {\n    background: var(--primary-color);\n    color: #fff;\n    opacity: 1;\n}\n\n[data-theme=\"dark\"] .cmd-palette-toggle-pill {\n    background: rgba(255, 255, 255, 0.1);\n}\n\n[data-theme=\"dark\"] .cmd-palette-toggle-pill.on {\n    background: var(--primary-color);\n    color: #fff;\n}\n\n.cmd-palette-row-icon {\n    flex-shrink: 0;\n    color: var(--text-color);\n    opacity: 0.6;\n}\n\n.cmd-palette-row.selected .cmd-palette-row-icon {\n    opacity: 0.85;\n    color: var(--primary-color);\n}\n\n.cmd-palette-row.selected.danger .cmd-palette-row-icon {\n    color: #DC2626;\n}\n\n[data-theme=\"dark\"] .cmd-palette-row.selected.danger .cmd-palette-row-icon {\n    color: #F87171;\n}\n\n.cmd-palette-row-label {\n    flex: 1;\n    min-width: 0;\n    font-size: 0.88em;\n    color: var(--text-color);\n    white-space: nowrap;\n    overflow: hidden;\n    text-overflow: ellipsis;\n}\n\n.cmd-palette-row-hint {\n    flex-shrink: 0;\n    font-size: 0.75em;\n    color: var(--text-color);\n    opacity: 0.4;\n    white-space: nowrap;\n}\n\n.cmd-palette-enter-hint {\n    flex-shrink: 0;\n    color: var(--primary-color);\n    opacity: 0.5;\n}\n\n.cmd-palette-match {\n    font-weight: 700;\n    color: var(--primary-color);\n}\n\n/* ─── Rename Hint ─── */\n.cmd-palette-rename-hint {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 6px;\n    padding: 20px 16px;\n    font-size: 0.8em;\n    color: var(--text-color);\n    opacity: 0.5;\n}\n\n.cmd-palette-rename-hint kbd {\n    font-family: \"SF Mono\", Monaco, \"Cascadia Code\", \"Roboto Mono\", Consolas, \"Courier New\", monospace;\n    font-size: 0.9em;\n    padding: 1px 5px;\n    border-radius: 3px;\n    background: rgba(0, 0, 0, 0.05);\n    border: 1px solid rgba(0, 0, 0, 0.08);\n    line-height: 1.3;\n}\n\n[data-theme=\"dark\"] .cmd-palette-rename-hint kbd {\n    background: rgba(255, 255, 255, 0.06);\n    border-color: rgba(255, 255, 255, 0.08);\n}\n\n/* ─── Empty State ─── */\n.cmd-palette-empty {\n    padding: 24px 16px;\n    text-align: center;\n    font-size: 0.85em;\n    color: var(--text-color);\n    opacity: 0.45;\n}\n\n/* ─── Footer ─── */\n.cmd-palette-footer {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n    padding: 8px 16px;\n    border-top: 1px solid rgba(0, 0, 0, 0.06);\n}\n\n[data-theme=\"dark\"] .cmd-palette-footer {\n    border-top-color: rgba(255, 255, 255, 0.06);\n}\n\n.cmd-palette-footer-hint {\n    display: inline-flex;\n    align-items: center;\n    gap: 4px;\n    font-size: 0.7em;\n    color: var(--text-color);\n    opacity: 0.4;\n}\n\n.cmd-palette-footer-hint kbd {\n    font-family: \"SF Mono\", Monaco, \"Cascadia Code\", \"Roboto Mono\", Consolas, \"Courier New\", monospace;\n    font-size: 0.9em;\n    padding: 1px 5px;\n    border-radius: 3px;\n    background: rgba(0, 0, 0, 0.05);\n    border: 1px solid rgba(0, 0, 0, 0.08);\n    line-height: 1.3;\n}\n\n[data-theme=\"dark\"] .cmd-palette-footer-hint kbd {\n    background: rgba(255, 255, 255, 0.06);\n    border-color: rgba(255, 255, 255, 0.08);\n}\n\n/* ─── Animations ─── */\n@keyframes cmdOverlayIn {\n    from { opacity: 0; }\n    to { opacity: 1; }\n}\n\n@keyframes cmdCardIn {\n    from {\n        opacity: 0;\n        transform: translateY(-12px) scale(0.97);\n    }\n    to {\n        opacity: 1;\n        transform: translateY(0) scale(1);\n    }\n}\n\n/* ─── Performance Mode ─── */\n.performance-mode .cmd-palette-overlay {\n    backdrop-filter: none;\n    -webkit-backdrop-filter: none;\n    animation: none;\n}\n\n.performance-mode .cmd-palette-card {\n    backdrop-filter: none;\n    -webkit-backdrop-filter: none;\n    animation: none;\n    background: var(--bg-color);\n}\n\n.performance-mode .cmd-palette-row {\n    transition: none;\n}\n\n/* ─── Reduced Motion ─── */\n@media (prefers-reduced-motion: reduce) {\n    .cmd-palette-overlay,\n    .cmd-palette-card {\n        animation: none;\n    }\n    .cmd-palette-row {\n        transition: none;\n    }\n}\n"],"sourceRoot":""}]);
