  height: 585px;
  max-height: 585px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.main-content-wrapper {
  padding: 0 5px 0 5px;
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.hr {
	height: 1px;
	border-top: 1px solid var(--divider-color);
	margin: 3px 0;
}

p {
	margin:0;
}

/* Bottom fade overlay */
.bottom-fade-overlay {
	position: fixed;
	bottom: 0;
	left: 0;
	right: 0;
	height: 15px;
	background: linear-gradient(
		to bottom,
		transparent 0%,
		var(--bg-color) 100%
	);
	pointer-events: none;
	z-index: 1000;
}

/* ========================================
   FULL PAGE MODE - Layout overrides
   ======================================== */
.App.fullpage {
	height: 100vh;
	max-height: 100vh;
}

.App.fullpage .main-content-wrapper {
	position: relative;
