    border-color: color-mix(in srgb, var(--primary-color) 65%, transparent);
    box-shadow:
        0 3px 10px rgba(22, 152, 226, 0.22),
        inset 0 0 0 1px rgba(255, 255, 255, 0.24);
}

.fp-sidebar-add-folder:active {
    transform: scale(0.96);
}

[data-theme="dark"] .fp-sidebar-folders-title {
    text-shadow: none;
    opacity: 0.9;
}

[data-theme="dark"] .fp-sidebar-add-folder {
    background: color-mix(in srgb, var(--primary-color) 24%, transparent);
    border-color: color-mix(in srgb, var(--primary-color) 70%, transparent);
    box-shadow:
        0 2px 8px rgba(10, 25, 56, 0.36),
