    border-color: color-mix(in srgb, var(--primary-color) 85%, transparent);
    box-shadow:
        0 4px 12px rgba(10, 25, 56, 0.44),
        inset 0 0 0 1px rgba(255, 255, 255, 0.12);
}

.fp-sidebar-folder-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.fp-sidebar-folder-row {
    position: relative;
}

.fp-sidebar-folder-row-sorting {
    z-index: 2;
}

.fp-sidebar-folder-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    border-radius: var(--fp-radius-sm, 8px);
    border: none;
    background: transparent;
    color: var(--text-color);
    font-family: var(--fp-font-body);
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    text-align: left;
    width: 100%;
    transition: background var(--fp-duration) var(--fp-ease);
}

.fp-sidebar-folder-row-sorting .fp-sidebar-folder-item {
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.12);
    background: color-mix(in srgb, var(--primary-color) 8%, var(--fp-surface-elevated, var(--section-bg-color)));
}

.fp-sidebar-folder-item:hover {
    background: var(--fp-border, var(--setting-row-hover-bg-color));
}

.fp-sidebar-folder-item.active {
    background: var(--primary-hover-bg);
    color: var(--primary-color);
    font-weight: 600;
}

.fp-sidebar-folder-icon {
