    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform var(--fp-duration) var(--fp-ease-spring);
}

.fp-sidebar-folder-item:hover .fp-sidebar-folder-icon {
    transform: scale(1.1);
}

.fp-sidebar-folder-name {
