.fp-card-matching-tab-info {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 0;
    flex: 1;
}

.fp-card-matching-tab-title {
    font-family: var(--fp-font-body);
    font-size: 13.5px;
    font-weight: 600;
    line-height: 1.35;
    color: var(--text-color);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    letter-spacing: -0.005em;
}

.fp-card-matching-tab-url {
    font-size: 11.5px;
    font-family: 'SF Mono', 'Menlo', 'Consolas', monospace;
    color: var(--settings-row-text-color);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    line-height: 1.35;
    letter-spacing: -0.01em;
}

/* Highlight inside tab titles and URLs */
.fp-card-matching-tab-title .fp-card-search-match {
    background: rgba(251, 191, 36, 0.35);
    color: var(--text-color);
    padding: 1px 3px;
    border-radius: 3px;
    font-weight: 700;
}

.fp-card-matching-tab-url .fp-card-search-match {
    background: rgba(251, 191, 36, 0.28);
    color: var(--text-color);
    padding: 1px 3px;
    border-radius: 3px;
}

[data-theme="dark"] .fp-card-matching-tab-title .fp-card-search-match {
    background: rgba(251, 191, 36, 0.38);
}

[data-theme="dark"] .fp-card-matching-tab-url .fp-card-search-match {
    background: rgba(251, 191, 36, 0.30);
}

.fp-card-matching-tabs-more {
    display: block;
    padding: 10px 14px;
    margin-top: 4px;
    border: none;
    background: none;
    color: var(--primary-color);
    font-family: var(--fp-font-body);
    font-size: 12.5px;
    font-weight: 600;
    cursor: pointer;
    text-align: left;
    border-radius: var(--fp-radius-sm, 8px);
    transition: background 0.15s var(--fp-ease, ease);
}

.fp-card-matching-tabs-more:hover {
    background: var(--primary-hover-bg);
}

.fp-card-meta-match-badge {
    background: rgba(22, 152, 226, 0.1);
    color: var(--primary-color);
}

[data-theme="dark"] .fp-card-meta-match-badge {
    background: rgba(58, 119, 216, 0.22);
}

/* ---- Reduced Motion ---- */
@media (prefers-reduced-motion: reduce) {
    .fp-card-badge.tracking,
    .fp-card-highlighted,
    .fp-card-lightning,
    .fp-card-deleting,
    .fp-card.fp-card-tracking {
        animation: none !important;
    }
    .fp-card,
    .fp-card::before,
    .fp-card-actions,
    .fp-card-color-picker,
    .fp-card-favicon {
        transition: none !important;
    }
}
