ellipsis;\n\twhite-space: nowrap;\n\tline-height: 1.2;\n\tletter-spacing: 0.2px;\n\topacity: 0.95;\n\ttransition: opacity 0.3s ease;\n}\n\n.login-section:hover .header_text {\n\topacity: 1;\n}\n\n.email {\n\tfont-size: 0.62em;\n\tfont-weight: 500;\n\tcolor: var(--footer-text-color);\n\toverflow: hidden;\n\ttext-overflow: ellipsis;\n\twhite-space: nowrap;\n\tmax-width: 180px;\n\tline-height: 1.1;\n\topacity: 0.8;\n\ttransition: opacity 0.3s ease;\n}\n\n.login-section:hover .email {\n\topacity: 0.9;\n}\n\n/* ═══════════════════════════════════════════\n   Login Section — Compact (fullpage mode)\n   ═══════════════════════════════════════════ */\n.login-section-compact {\n\tgap: 0;\n\tpadding: 0;\n\tposition: relative;\n\toverflow: visible;\n}\n\n.login-section-compact:hover {\n\tbackground: none;\n\tbackdrop-filter: none;\n\t-webkit-backdrop-filter: none;\n\ttransform: none;\n}\n\n.compact-user-trigger {\n\tdisplay: flex;\n\talign-items: center;\n\tgap: 6px;\n\tpadding: 4px 10px;\n\tborder-radius: 10px;\n\tcursor: pointer;\n\ttransition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n}\n\n.compact-user-trigger:hover {\n\tbackground: rgba(0, 0, 0, 0.06);\n}\n\n[data-theme=\"dark\"] .compact-user-trigger:hover {\n\tbackground: rgba(255, 255, 255, 0.08);\n}\n\n.compact-user-trigger:active {\n\ttransform: scale(0.97);\n}\n\n.login-section-compact .header_text {\n\tmax-width: 120px;\n\tfont-size: 0.72em;\n\tline-height: 1;\n}\n\n/* ─── User Context Menu ─── */\n.user-context-menu {\n\tposition: absolute;\n\ttop: calc(100% + 6px);\n\tright: 0;\n\tmin-width: 160px;\n\tbackground: var(--bg-color);\n\tborder: 1px solid rgba(0, 0, 0, 0.12);\n\tborder-radius: 10px;\n\tbox-shadow:\n\t\t0 8px 24px rgba(0, 0, 0, 0.14),\n\t\t0 2px 8px rgba(0, 0, 0, 0.08);\n\tpadding: 4px;\n\tz-index: 60000;\n\tanimation: menuFadeIn 0.15s ease-out;\n}\n\n[data-theme=\"dark\"] .user-context-menu {\n\tborder-color: rgba(255, 255, 255, 0.1);\n\tbox-shadow:\n\t\t0 8px 24px rgba(0, 0, 0, 0.35),\n\t\t0 2px 8px rgba(0, 0, 0, 0.2);\n}\n\n@keyframes menuFadeIn {\n\tfrom { opacity: 0; transform: translateY(-4px); }\n\tto { opacity: 1; transform: translateY(0); }\n}\n\n.user-context-item {\n\tdisplay: flex;\n\talign-items: center;\n\tgap: 8px;\n\twidth: 100%;\n\tpadding: 8px 12px;\n\tborder: none;\n\tborder-radius: 6px;\n\tbackground: none;\n\tcolor: var(--text-color);\n\tfont-size: 0.9em;\n\tfont-weight: 500;\n\tcursor: pointer;\n\ttransition: background 0.15s ease;\n\twhite-space: nowrap;\n}\n\n.user-context-item:hover {\n\tbackground: rgba(0, 0, 0, 0.06);\n}\n\n[data-theme=\"dark\"] .user-context-item:hover {\n\tbackground: rgba(255, 255, 255, 0.08);\n}\n\n/* Account info header */\n.user-context-header {\n\tpadding: 8px 12px;\n}\n\n.user-context-name {\n\tfont-size: 0.95em;\n\tfont-weight: 600;\n\tcolor: var(--text-color);\n\tline-height: 1.3;\n}\n\n.user-context-email {\n\tfont-size: 0.82em;\n\tfont-weight: 400;\n\tcolor: var(--footer-text-color);\n\topacity: 0.75;\n\tline-height: 1.3;\n\tmargin-top: 1px;\n}\n\n.user-context-divider {\n\theight: 1px;\n\tmargin: 2px 8px;\n\tbackground: rgba(0, 0, 0, 0.08);\n}\n\n[data-theme=\"dark\"] .user-context-divider {\n\tbackground: rgba(255, 255, 255, 0.08);\n}\n\n/* ═══════════════════════════════════════════\n   Popup Mode — Action Buttons\n   ═══════════════════════════════════════════ */\n.header-action-btn {\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n\twidth: 40px;\n\theight: 40px;\n\tborder: 1px solid rgba(0, 0, 0, 0.1);\n\tbackground: rgba(0, 0, 0, 0.04);\n\tbackdrop-filter: blur(8px);\n\t-webkit-backdrop-filter: blur(8px);\n\tborder-radius: 10px;\n\tcolor: var(--text-color);\n\tcursor: pointer;\n\ttransition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n\topacity: 0.75;\n\tposition: relative;\n\toverflow: hidden;\n\tflex-shrink: 0;\n}\n\n.header-action-btn::before {\n\tcontent: '';\n\tposition: absolute;\n\tinset: 0;\n\tborder-radius: inherit;\n\tbackground: linear-gradient(135deg,\n\t\trgba(22, 152, 226, 0.12),\n\t\trgba(139, 93, 255, 0.1),\n\t\trgba(255, 140, 66, 0.08));\n\topacity: 0;\n\ttransition: opacity 0.3s ease;\n}\n\n.header-action-btn:hover {\n\topacity: 1;\n\ttransform: scale(1.06);\n\tborder-color: rgba(139, 93, 255, 0.3);\n\tbox-shadow: 0 2px 10px rgba(139, 93, 255, 0.1);\n}\n\n.header-action-btn:hover::before {\n\topacity: 1;\n}\n\n.header-action-btn:active {\n\ttransform: scale(0.94);\n}\n\n[data-theme=\"dark\"] .header-action-btn {\n\tborder-color: rgba(255, 255, 255, 0.1);\n\tbackground: rgba(255, 255, 255, 0.06);\n}\n\n[data-theme=\"dark\"] .header-action-btn:hover {\n\tborder-color: rgba(139, 93, 255, 0.3);\n\tbox-shadow: 0 2px 12px rgba(139, 93, 255, 0.15);\n}\n\n/* Override settings button in popup to match action buttons */\n.header-popup .settings-wrapper {\n\tposition: relative;\n\ttop: auto;\n\tright: auto;\n}\n\n.header-popup .settings-button {\n\twidth: 40px;\n\theight: 40px;\n\tborder-radius: 10px;\n}\n\n/* ─── Vertical Separator (shared with FPTopBar) ─── */\n.header-separator {\n\twidth: 1px;\n\theight: 20px;\n\tbackground: linear-gradient(\n\t\t180deg,\n\t\ttransparent,\n\t\trgba(0, 0, 0, 0.12) 30%,\n\t\trgba(0, 0, 0, 0.12) 70%,\n\t\ttransparent\n\t);\n\tflex-shrink: 0;\n}\n\n[data-theme=\"dark\"] .header-separator {\n\tbackground: linear-gradient(\n\t\t180deg,\n\t\ttransparent,\n\t\trgba(255, 255, 255, 0.12) 30%,\n\t\trgba(255, 255, 255, 0.12) 70%,\n\t\ttransparent\n\t);\n}\n\n/* ─── Sync Status (fullpage control strip) ─── */\n.sync-status {\n\tdisplay: flex;\n\talign-items: center;\n\tgap: 6px;\n\tpadding: 4px 8px;\n\tborder-radius: 10px;\n\tcursor: default;\n\ttransition: background 0.2s ease;\n}\n\n.sync-status:hover {\n\tbackground: rgba(0, 0, 0, 0.04);\n}\n\n[data-theme=\"dark\"] .sync-status:hover {\n\tbackground: rgba(255, 255, 255, 0.06);\n}\n\n.sync-dot {\n\twidth: 9px;\n\theight: 9px;\n\tborder-radius: 50%;\n\tflex-shrink: 0;\n\ttransition: all 0.3s ease;\n}\n\n.sync-dot.connected {\n\tbackground: #34c759;\n\tbox-shadow: 0 0 6px rgba(52, 199, 89, 0.5);\n}\n\n.sync-dot.syncing {\n\tbackground: #ffcc00;\n\tbox-shadow: 0 0 6px rgba(255, 204, 0, 0.5);\n\tanimation: pulse-dot 1.4s ease-in-out infinite;\n}\n\n.sync-dot.disconnected {\n\tbackground: #8e8e93;\n\tbox-shadow: none;\n}\n\n@keyframes pulse-dot {\n\t0%, 100% { opacity: 1; transform: scale(1); }\n\t50% { opacity: 0.5; transform: scale(0.85); }\n}\n\n.sync-label {\n\tfont-size: 0.85em;\n\tfont-weight: 500;\n\tcolor: var(--text-color);\n\twhite-space: nowrap;\n\topacity: 0.8;\n\tline-height: 1;\n}\n\n.sync-status-action {\n\tdisplay: inline-flex;\n\talign-items: center;\n\tjustify-content: center;\n\twidth: 24px;\n\theight: 24px;\n\tborder: none;\n\tborder-radius: 999px;\n\tbackground: transparent;\n\tcolor: var(--text-color);\n\topacity: 0.78;\n\tcursor: pointer;\n\ttransition: background 0.2s ease, opacity 0.2s ease, transform 0.2s ease;\n}\n\n.sync-status-action:hover:not(:disabled) {\n\tbackground: rgba(0, 0, 0, 0.06);\n\topacity: 1;\n}\n\n[data-theme=\"dark\"] .sync-status-action:hover:not(:disabled) {\n\tbackground: rgba(255, 255, 255, 0.08);\n}\n\n.sync-status-action:active:not(:disabled) {\n\ttransform: scale(0.95);\n}\n\n.sync-status-action:disabled {\n\topacity: 0.45;\n\tcursor: default;\n}\n"],"sourceRoot":""}]);
