    position: relative;
    display: inline-flex;
    align-items: center;
    min-width: 150px;
    max-width: 200px;
    height: 28px;
    background: transparent;
    border-radius: 6px;
    transition: all 0.2s ease;
    overflow: hidden;
}

.autosave-wrapper:hover {
    background: rgba(var(--primary-color-rgb, 52, 152, 219), 0.05);
    box-shadow: 0 0 0 1px rgba(var(--primary-color-rgb, 52, 152, 219), 0.2);
}

.autosave-wrapper:focus-within {
    background: var(--section-bg-color);
    box-shadow: 0 0 0 2px var(--primary-color);
    transform: translateY(-1px);
}

.edit-icon {
    position: absolute;
    left: 6px;
    top: 50%;
    transform: translateY(-50%);
    width: 14px;
    height: 14px;
    opacity: 0.4;
    transition: all 0.2s ease;
    cursor: pointer;
    z-index: 2;
}

.autosave-wrapper:hover .edit-icon {
    opacity: 0.7;
    color: var(--primary-color);
}

.autosave-wrapper:focus-within .edit-icon {
    opacity: 1;
    color: var(--primary-color);
}

.autosave-textbox {
    width: 100%;
    height: 28px;
    padding: 0 30px 0 26px;
    font-size: 13px !important;
    font-weight: 500;
    background: transparent;
    border: none;
    color: var(--text-color);
    text-overflow: ellipsis;
    overflow: hidden;
    overflow-x: hidden;
    white-space: nowrap;
    outline: none;
    transition: all 0.2s ease;
    box-sizing: border-box;
}

.autosave-textbox::placeholder {
    color: var(--secondary-text-color);
    opacity: 0.6;
    font-weight: 400;
}

.checkmark__circle {
    stroke-dasharray: 166;
    stroke-dashoffset: 166;
    stroke-width: 2;
    stroke-miterlimit: 10;
    stroke: #22c55e;
    fill: none;
    animation: stroke 0.4s cubic-bezier(0.65, 0, 0.45, 1) 0.1s forwards;
  }
  
  .checkmark {
    width: 12px;
    height: 12px;
    position: absolute;
    top: 50%;
    right: 8px;
    transform: translateY(-50%);
    border-radius: 50%;
    display: block;
    stroke-width: 2;
    stroke: #fff;
    stroke-miterlimit: 10;
    box-shadow: inset 0px 0px 0px #22c55e;
    animation: fill .3s ease-in-out .2s forwards, checkmarkPop .2s ease-out .5s both;
    z-index: 3;
  }
  
  .checkmark__check {
    transform-origin: 50% 50%;
    stroke-dasharray: 48;
    stroke-dashoffset: 48;
    animation: stroke 0.3s cubic-bezier(0.65, 0, 0.45, 1) 0.4s forwards;
  }
  
  @keyframes stroke {
    100% {
      stroke-dashoffset: 0;
    }
  }
  @keyframes scale {
    0%, 100% {
      transform: none;
    }
    50% {
      transform: scale3d(1.1, 1.1, 1);
    }
  }
  @keyframes fill {
    100% {
      box-shadow: inset 0px 0px 0px 30px #22c55e;
    }
  }
  
  @keyframes checkmarkPop {
    0% {
      transform: translateY(-50%) scale(0.8);
      opacity: 0;
    }
    50% {
      transform: translateY(-50%) scale(1.1);
      opacity: 1;
    }
    100% {
      transform: translateY(-50%) scale(1);
      opacity: 1;
    }
  }

  .lds-ring {
    display: inline-block;
    position: absolute;
    top: 50%;
    right: 8px;
    transform: translateY(-50%);
    width: 12px;
    height: 12px;
    z-index: 3;
  }
  .lds-ring div {
    box-sizing: border-box;
    display: block;
    position: absolute;
    width: 8px;
    height: 8px;
    margin: 1px;
    border: 1.5px solid var(--primary-color);
    border-radius: 50%;
    animation: lds-ring 1s cubic-bezier(0.5, 0, 0.5, 1) infinite;
    border-color: var(--primary-color) transparent transparent transparent;
    opacity: 0.8;
  }
  .lds-ring div:nth-child(1) {
    animation-delay: -0.45s;
  }
  .lds-ring div:nth-child(2) {
    animation-delay: -0.3s;
  }
  .lds-ring div:nth-child(3) {
    animation-delay: -0.15s;
  }
  @keyframes lds-ring {
    0% {
      transform: rotate(0deg);
    }
    100% {
      transform: rotate(360deg);
    }
  }`, "",{"version":3,"sources":["webpack://./app/AutoSaveTextbox.css"],"names":[],"mappings":"AAAA;IACI,kBAAkB;IAClB,oBAAoB;IACpB,mBAAmB;IACnB,gBAAgB;IAChB,gBAAgB;IAChB,YAAY;IACZ,uBAAuB;IACvB,kBAAkB;IAClB,yBAAyB;IACzB,gBAAgB;AACpB;;AAEA;IACI,8DAA8D;IAC9D,uEAAuE;AAC3E;;AAEA;IACI,mCAAmC;IACnC,0CAA0C;IAC1C,2BAA2B;AAC/B;;AAEA;IACI,kBAAkB;IAClB,SAAS;IACT,QAAQ;IACR,2BAA2B;IAC3B,WAAW;IACX,YAAY;IACZ,YAAY;IACZ,yBAAyB;IACzB,eAAe;IACf,UAAU;AACd;;AAEA;IACI,YAAY;IACZ,2BAA2B;AAC/B;;AAEA;IACI,UAAU;IACV,2BAA2B;AAC/B;;AAEA;IACI,WAAW;IACX,YAAY;IACZ,sBAAsB;IACtB,0BAA0B;IAC1B,gBAAgB;IAChB,uBAAuB;IACvB,YAAY;IACZ,wBAAwB;IACxB,uBAAuB;IACvB,gBAAgB;IAChB,kBAAkB;IAClB,mBAAmB;IACnB,aAAa;IACb,yBAAyB;IACzB,sBAAsB;AAC1B;;AAEA;IACI,kCAAkC;IAClC,YAAY;IACZ,gBAAgB;AACpB;;AAEA;IACI,qBAAqB;IACrB,sBAAsB;IACtB,eAAe;IACf,qBAAqB;IACrB,eAAe;IACf,UAAU;IACV,mEAAmE;EACrE;;EAEA;IACE,WAAW;IACX,YAAY;IACZ,kBAAkB;IAClB,QAAQ;IACR,UAAU;IACV,2BAA2B;IAC3B,kBAAkB;IAClB,cAAc;IACd,eAAe;IACf,YAAY;IACZ,qBAAqB;IACrB,qCAAqC;IACrC,gFAAgF;IAChF,UAAU;EACZ;;EAEA;IACE,yBAAyB;IACzB,oBAAoB;IACpB,qBAAqB;IACrB,mEAAmE;EACrE;;EAEA;IACE;MACE,oBAAoB;IACtB;EACF;EACA;IACE;MACE,eAAe;IACjB;IACA;MACE,+BAA+B;IACjC;EACF;EACA;IACE;MACE,0CAA0C;IAC5C;EACF;;EAEA;IACE;MACE,sCAAsC;MACtC,UAAU;IACZ;IACA;MACE,sCAAsC;MACtC,UAAU;IACZ;IACA;MACE,oCAAoC;MACpC,UAAU;IACZ;EACF;;EAEA;IACE,qBAAqB;IACrB,kBAAkB;IAClB,QAAQ;IACR,UAAU;IACV,2BAA2B;IAC3B,WAAW;IACX,YAAY;IACZ,UAAU;EACZ;EACA;IACE,sBAAsB;IACtB,cAAc;IACd,kBAAkB;IAClB,UAAU;IACV,WAAW;IACX,WAAW;IACX,wCAAwC;IACxC,kBAAkB;IAClB,4DAA4D;IAC5D,sEAAsE;IACtE,YAAY;EACd;EACA;IACE,uBAAuB;EACzB;EACA;IACE,sBAAsB;EACxB;EACA;IACE,uBAAuB;EACzB;EACA;IACE;MACE,uBAAuB;IACzB;IACA;MACE,yBAAyB;IAC3B;EACF","sourcesContent":[".autosave-wrapper {\n    position: relative;\n    display: inline-flex;\n    align-items: center;\n    min-width: 150px;\n    max-width: 200px;\n    height: 28px;\n    background: transparent;\n    border-radius: 6px;\n    transition: all 0.2s ease;\n    overflow: hidden;\n}\n\n.autosave-wrapper:hover {\n    bac