    background: linear-gradient(90deg, var(--primary-color) 0%, rgba(22, 152, 226, 0.18) 100%);
}

.current-window-live-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    border-radius: 999px;
    background: rgba(22, 152, 226, 0.12);
    color: var(--primary-color);
    font-size: 12px;
    font-weight: 700;
}

.current-window-panel-content {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.current-window-tabs-section {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.current-window-group {
    border: 1px solid var(--divider-color);
    border-radius: 10px;
    overflow: hidden;
    background: color-mix(in srgb, var(--section-bg-color) 92%, transparent);
}

.current-window-group-header {
    align-items: center;
    justify-content: space-between;
}

.current-window-group-title {
    gap: 8px;
}

.current-window-group-color {
    width: 8px;
    height: 8px;
    border-radius: 999px;
}

.current-window-group-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 20px;
    height: 20px;
    padding: 0 6px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.7);
    color: inherit;
    font-size: 11px;
    font-weight: 700;
}

.current-window-group-actions {
    margin-left: auto;
}

.current-window-group-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: var(--text-color);
    cursor: pointer;
}

.current-window-group-toggle:hover {
    background: rgba(255, 255, 255, 0.08);
}

.current-window-group-tabs {
    padding: 6px 0;
}

.current-window-tab-line {
    width: 100%;
}

.current-window-tab-row {
    cursor: default;
}

.current-window-tab-row:hover {
    background-color: var(--single-tab-row-hover-color);
}

.current-window-tab-row.current-window-tab-row-context-active {
    background-color: var(--single-tab-row-hover-color);
}

.fp-detail-panel .current-window-tab-row .actions-col {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 6px;
    opacity: 1 !important;
}

.fp-detail-panel .current-window-tab-row .tab-action-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;
    border: none !important;
    background: transparent !important;
    color: var(--text-secondary-color) !important;
    box-shadow: none !important;
    transform: none !important;
    outline: none !important;
}

.fp-detail-panel .current-window-tab-row .tab-action-btn:focus-visible {
    outline: none;
    box-shadow: 0 0 0 3px rgba(var(--primary-color-rgb, 52, 152, 219), 0.16);
}

.fp-detail-panel .current-window-tab-row .current-window-tab-hover-action {
    width: auto !important;
    min-width: 0 !important;
    height: 32px !important;
    padding: 0 15px !important;
    border-radius: 999px !important;
    background: rgba(255, 255, 255, 0.09) !important;
    opacity: 0;
    pointer-events: none;
    transform: translateX(4px);
    transition: opacity 160ms ease, transform 160ms ease, background-color 160ms ease, color 160ms ease;
}

.fp-detail-panel .current-window-tab-row:hover .current-window-tab-hover-action,
.fp-detail-panel .current-window-tab-row:focus-within .current-window-tab-hover-action {
    opacity: 1;
    pointer-events: auto;
    transform: translateX(0);
}

.fp-detail-panel .current-window-tab-row .current-window-tab-hover-action span {
    font-size: 11.5px;
    font-weight: 500;
    letter-spacing: 0.02em;
    line-height: 1;
}

.fp-detail-panel .current-window-tab-row .current-window-tab-icon {
    width: 12px !important;
    height: 12px !important;
    min-width: 12px !important;
    min-height: 12px !important;
    flex-shrink: 0;
    opacity: 0.78;
}

.fp-detail-panel .current-window-tab-row .current-window-tab-icon-focus {
    opacity: 0.9;
}

.fp-detail-panel .current-window-tab-row .current-window-tab-icon-open,
.fp-detail-panel .current-window-tab-row .current-window-tab-icon-close {
    width: 9px !important;
    height: 9px !important;
    min-width: 9px !important;
    min-height: 9px !important;
    opacity: 0.68;
}

.fp-detail-panel .current-window-tab-row .current-window-tab-hover-action:hover:not(:disabled) {
    transform: translateX(0);
    background: rgba(255, 255, 255, 0.16) !important;
}

.fp-detail-panel .current-window-tab-row .current-window-tab-hover-action:active:not(:disabled) {
    transform: scale(0.96);
}

.fp-detail-panel .current-window-tab-row .current-window-tab-focus-btn {
    color: var(--primary-color) !important;
    background: rgba(var(--primary-color-rgb, 52, 152, 219), 0.18) !important;
}

.fp-detail-panel .current-window-tab-row .current-window-tab-focus-btn:hover:not(:disabled) {
    background: rgba(var(--primary-color-rgb, 52, 152, 219), 0.24) !important;
}

.fp-detail-panel .current-window-tab-row .current-window-tab-open-btn {
    color: var(--text-color) !important;
    background: rgba(255, 255, 255, 0.1) !important;
}

.fp-detail-panel .current-window-tab-row .current-window-tab-close-btn {
    color: #dd7c84 !important;
    background: rgba(224, 108, 117, 0.14) !important;
    border: none !important;
    box-shadow: none !important;
}

.fp-detail-panel .current-window-tab-row .current-window-tab-close-btn:hover:not(:disabled) {
    background: rgba(224, 108, 117, 0.2) !important;
    color: #d94f5a !important;
}

.current-window-empty {
    padding: 18px 4px 8px;
    color: var(--settings-row-text-color);
    text-align: center;
}

.current-window-empty p {
    margin: 0;
}

.fp-tab-ctx-menu {
    position: fixed;
    z-index: 10001;
    min-width: 196px;
    padding: 6px;
    border: 1px solid color-mix(in srgb, var(--divider-color) 85%, rgba(255, 255, 255, 0.18));
    border-radius: 12px;
    background: color-mix(in srgb, var(--bg-color) 92%, #1f2430);
    backdrop-filter: blur(14px) saturate(135%);
    -webkit-backdrop-filter: blur(14px) saturate(135%);
    box-shadow:
        0 18px 40px rgba(0, 0, 0, 0.32),
        0 4px 18px rgba(0, 0, 0, 0.16);
}

.fp-tab-ctx-item {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: var(--text-color);
    cursor: pointer;
    padding: 10px 12px;
    text-align: left;
    font-size: 13px;
}

.fp-tab-ctx-item:hover:not(:disabled) {
    background: var(--single-tab-row-hover-color);
}

.fp-tab-ctx-item:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.fp-tab-ctx-item.danger {
    color: var(--delete-button-color, #d14343);
}

.fp-tab-ctx-divider {
    height: 1px;
    margin: 6px 4px;
    background: var(--divider-color);
}
